Given two integers a and b(b != 0), the task is to return the fraction a/b in string format. If the fractional part is repeating, enclose the repeating part in parentheses.Examples: Input: a = 1, b = 2Output: "0.5"Explanation: 1/2 = 0.5 with no repeating part.Input: a = 50, b = 22Output: "2.(27)"Explanation: 50/22 = 2.27272727... Since fractional part (27) is repeating, it is enclosed in parentheses.Try It YourselfApproach: The idea is to first calculate the integral quotient (absolute part before decimal point) and then calculate the fractional part. To check if the fractional part is repeating, insert the remainder (a % b) in a hash map with key as remainder and value as the index position at which this remainder occurs. If at any point of time, the remainder becomes zero, then there doesn't exist a repeating fraction otherwise if the remainder is already found in the map, then there exists a repeating fraction.
            C++

    // C++ Program to convert fraction to string

#include <iostream>
#include <unordered_map>
using namespace std;

string calculateFraction(int a, int b) {

    // If the numerator is zero, answer is 0
    if (a == 0)
        return "0";

    // If exactly one of the numerator or denominator
    // is negative, then result will be negative
    string res = (a < 0) ^ (b < 0) ? "-" : "";

    a = abs(a);
    b = abs(b);

    // Calculate and Append the part before decimal point
    res += to_string(a / b);

    int rem = a % b;

    // If completely divisible, return res
    if (rem == 0)
        return res;

    res.append(".");
    unordered_map<int, int> mp;

    while (rem > 0) {

        // If this remainder is already seen,
        // then there exists a repeating fraction.
        if (mp.find(rem) != mp.end()) {

            res.insert(mp[rem], "(");
            res.append(")");
            break;
        }

        // If the remainder is seen for the first time,
        // store its index
        mp[rem] = res.size();

        rem = rem * 10;

        // Calculate quotient, append it to result and
        // calculate next remainder
        res += to_string(rem / b);
        rem = rem % b;
    }

    return res;
}

int main() {
    int a = 50, b = 22;
    cout << calculateFraction(a, b) << endl;
    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* calculateFraction(int a, int b) {
    // If the numerator is zero, answer is 0
    if (a == 0) {
        char* result = (char*)malloc(2);
        strcpy(result, "0");
        return result;
    }

    // If exactly one of the numerator or denominator
    // is negative, then result will be negative
    char* res = (char*)malloc(100);
    int isNegative = (a < 0) ^ (b < 0);
    if (isNegative) {
        strcpy(res, "-");
    } else {
        strcpy(res, "");
    }

    a = abs(a);
    b = abs(b);

    // Calculate and Append the part before decimal point
    char temp[20];
    sprintf(temp, "%d", a / b);
    strcat(res, temp);

    int rem = a % b;

    // If completely divisible, return res
    if (rem == 0) {
        return res;
    }

    strcat(res, ".");
    int index = strlen(res);
    int seen[10000] = {0}; // To store the index of seen remainders

    while (rem > 0) {
        // If this remainder is already seen,
        // then there exists a repeating fraction.
        if (seen[rem] != 0) {
            // Insert '(' at the index of first occurrence
            memmove(res + seen[rem] + 1, res + seen[rem], index - seen[rem] + 1);
            res[seen[rem]] = '(';
            strcat(res, ")");
            break;
        }

        // If the remainder is seen for the first time,
        // store its index
        seen[rem] = index;

        rem = rem * 10;

        // Calculate quotient, append it to result and
        // calculate next remainder
        sprintf(temp, "%d", rem / b);
        strcat(res, temp);
        rem = rem % b;
        index = strlen(res);
    }

    return res;
}

int main() {
    int a = 50, b = 22;
    char* result = calculateFraction(a, b);
    printf("%s\n", result);
    free(result);
    return 0;
}


